INSERT INTO t_p15395438_addict_clinic_site.shop_products (slug, category, title, subtitle, description, price, old_price, image_url, badge, options, is_digital, sort) VALUES
('hoodie-recovery', 'merch', 'Худи «Шаг за шагом»', 'Плотный хлопок 360 г/м², вышивка', 'Мягкое оверсайз-худи из органического хлопка с вышитым знаком клиники. Напоминание о том, что каждый день трезвости — это шаг. Часть выручки идёт в фонд бесплатных консультаций для родственников.', 5900, NULL, 'https://cdn.poehali.dev/projects/1eb84f6e-14c3-4877-b42b-93b6450a03c2/files/d8d4a55f-4431-4f10-92f3-861ec4b65511.jpg', 'Хит', 'S,M,L,XL,XXL', FALSE, 10),
('mug-tote-set', 'merch', 'Набор: кружка и шопер', 'Керамика 350 мл + холщовая сумка', 'Чёрная матовая кружка и прочный шопер из плотного хлопка. Хороший подарок человеку в ремиссии или близкому, который его поддерживает.', 2400, 2900, 'https://cdn.poehali.dev/projects/1eb84f6e-14c3-4877-b42b-93b6450a03c2/files/18f4c5ed-57c2-406b-bbd4-0163559ae1d7.jpg', '−17%', NULL, FALSE, 20),
('cert-consult', 'certificates', 'Сертификат на консультацию психолога', 'Очно или онлайн · 60 минут', 'Подарочный сертификат на индивидуальную консультацию психолога клиники. Анонимно. Действует 12 месяцев. Электронная версия придёт на почту сразу после оплаты.', 4000, NULL, 'https://cdn.poehali.dev/projects/1eb84f6e-14c3-4877-b42b-93b6450a03c2/files/36cacf7d-21cd-4566-bb65-556a167adab2.jpg', NULL, NULL, TRUE, 30),
('cert-family', 'certificates', 'Сертификат «Поддержка семьи»', '4 семейные сессии + месяц кабинета', 'Курс из четырёх встреч с семейным психологом и 30 дней полного доступа к кабинету для близких с ИИ-психологом. Подходит родственникам, которые не знают, с чего начать.', 18000, 22000, 'https://cdn.poehali.dev/projects/1eb84f6e-14c3-4877-b42b-93b6450a03c2/files/36cacf7d-21cd-4566-bb65-556a167adab2.jpg', 'Выгодно', NULL, TRUE, 40),
('cert-amount', 'certificates', 'Подарочный сертификат на сумму', 'Любые услуги клиники', 'Универсальный сертификат: можно оплатить консультацию, диагностику, курс терапии или реабилитацию. Действует 12 месяцев, анонимно.', 10000, NULL, 'https://cdn.poehali.dev/projects/1eb84f6e-14c3-4877-b42b-93b6450a03c2/files/36cacf7d-21cd-4566-bb65-556a167adab2.jpg', NULL, '5000,10000,25000,50000', TRUE, 50),
('book-family', 'books', 'Книга «Когда близкий пьёт»', 'Практическое руководство для семьи', 'Книга врачей и психологов клиники: как говорить с зависимым без скандалов, как перестать спасать и начать помогать, что делать при срыве. 240 страниц, твёрдая обложка.', 1200, NULL, 'https://cdn.poehali.dev/projects/1eb84f6e-14c3-4877-b42b-93b6450a03c2/files/0d00b46a-e2e0-4762-bc42-0ea59a66c179.jpg', 'Новинка', 'Печатная,Электронная', FALSE, 60),
('workbook-codependency', 'books', 'Рабочая тетрадь по созависимости', '12 недель упражнений', 'Пошаговые упражнения на основе КПТ и подхода CRAFT: дневник чувств, работа с границами, план заботы о себе. Можно проходить самостоятельно или вместе с психологом.', 890, NULL, 'https://cdn.poehali.dev/projects/1eb84f6e-14c3-4877-b42b-93b6450a03c2/files/b99c72ac-5869-4cab-ae01-eee204323e43.jpg', NULL, NULL, FALSE, 70),
('book-set', 'books', 'Комплект «Семья и выздоровление»', 'Книга + рабочая тетрадь', 'Книга «Когда близкий пьёт» и рабочая тетрадь по созависимости со скидкой. Лучший старт для родственника.', 1790, 2090, 'https://cdn.poehali.dev/projects/1eb84f6e-14c3-4877-b42b-93b6450a03c2/files/0d00b46a-e2e0-4762-bc42-0ea59a66c179.jpg', '−14%', NULL, FALSE, 80);